SELECT merchant_group, merchant, amount_range, grab_count FROM (SELECT CASE WHEN merchant IN ('Starbucks', 'Amazon') THEN 'core' ELSE 'other' END AS merchant_group, merchant, MAX(amount) - MIN(amount) AS amount_range, SUM(CASE WHEN merchant = 'Grab' THEN 1 ELSE 0 END) AS grab_count FROM transactions GROUP BY CASE WHEN merchant IN ('Starbucks', 'Amazon') THEN 'core' ELSE 'other' END, merchant) AS sub WHERE grab_count > 51 ORDER BY merchant_group DESC;
